const cleanNum = x => String(x || '').replace(/\D/g, '');
const emailRe = /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i;
const bannedEmail = /noreply|no-reply|example\.|sentry|wixpress|godaddy/i;
const extractEmail = html => {
  const s = String(html || '');
  const links = [...s.matchAll(/mailto:([^"'?\s>]+)/gi)].map(m => m[1].replace(/%40/gi, '@'));
  const plain = s.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [];
