};
const decodeLink = raw => {
  try {
    const m = String(raw || '').match(/[?&]uddg=([^&]+)/);
    const decoded = decodeURIComponent(m ? m[1] : raw);
    const u = new URL(decoded.startsWith('http') ? decoded : 'https:' + decoded);
