  } catch (e) { return null; }
};
const searchResults = async q => {
  try {
    const html = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://html.duckduckgo.com/html/?q=' + encodeURIComponent(q),
      timeout: 12000,
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; LumenAgentF/1.0)' }
    });
    const s = String(html || '');
    const links = [...s.matchAll(/<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi)];
    const snippets = [...s.matchAll(/<a[^>]+class="result__snippet"[^>]*>([\s\S]*?)<\/a>/gi)].map(m => m[1].replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').trim());
    return links.map((m, i) => {
      const u = decodeLink(m[1]);
      const title = m[2].replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&#x27;/g, "'").trim();
      return u ? { url: u.href, host: u.hostname, title, snippet: snippets[i] || '' } : null;
