const effectifBucket = raw => {
  const s = String(raw || '').trim();
  const code = s.match(/^(00|0[1-3]|1[12]|2[12]|3[12]|4[12]|5[1-3])$/);
  if (code) {
    const map = {
      '00': null, '01': '1-9', '02': '1-9', '03': '1-9',
      '11': '10-24', '12': '20-49', '21': '50-249', '22': '50-249',
      '31': '50-249', '32': '250-999', '41': '250-999',
      '42': '1000+', '51': '1000+', '52': '1000+', '53': '1000+'
    };
    return map[code[1]] || null;
  }
  const n = s.match(/(\d+)\s*(?:à|-|–|a)\s*(\d+)/i);
  if (n) {
    const low = Number(n[1]), high = Number(n[2]);
    if (high <= 9) return '1-9';
    if (low >= 10 && high <= 24) return '10-24';
    if (low >= 20 && high <= 49) return low < 25 ? '20-49' : '25-49';
    if (low >= 50 && high <= 249) return '50-249';


    if (low >= 250 && high <= 999) return '250-999';
    if (low >= 1000) return '1000+';
  }
  if (/1000|plus de 1000|1000 et plus/i.test(s)) return '1000+';
  return null;
};
const rankSize = b => b === '1-9' ? 0 : (['10-24','20-49','25-49','50-249'].includes(b) ? 1 : 2);
const normalizeName = s => String(s || '').toLocaleLowerCase('fr').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
const chooseCompany = (results, name, siret) => {
  const exactSiret = cleanNum(siret);
  if (exactSiret) {
    const exact = results.find(x => cleanNum(x.siege?.siret || x.siret) === exactSiret);
    if (exact) return exact;
  }
  const wanted = normalizeName(name);
  return results.find(x => {
    const got = normalizeName(x.nom_complet || x.nom_raison_sociale || x.denomination || '');
    return wanted && got && (got === wanted || got.includes(wanted) || wanted.includes(got));
  }) || results[0] || null;
};
const candidatesFromNotice = r => {
  let d = r.donnees || r.DONNEES || {};
  if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { d = {}; } }
  const siretValues = deepValues(d, /siret/i).flat(Infinity).map(cleanNum).filter(x => /^\d{14}$/.test(x));
  const nameValues = deepValues(d, /denomination|raisonsociale|nomtitulaire|nomattributaire|titulaire/i)
    .flat(Infinity).filter(x => typeof x === 'string' && x.trim());
  const names = [...nameValues, ...arr(r.titulaire).filter(x => typeof x === 'string'), ...arr(r.TITULAIRE).filter(x => typeof x === 'string')];
  const name = String(names[0] || '').trim();
  const siret = siretValues[0] || cleanNum(r.siret);
  if (!name && !siret) return null;
  const depValue = arr(r.code_departement || r.code_departement_prestation)[0];
  const dep = depValue ? String(depValue).padStart(2, '0') : null;
  const sourceUrl = r.url_avis || (r.idweb ? 'https://www.boamp.fr/pages/avis/?idweb=' + encodeURIComponent(r.idweb) : null);
  return {
