const enrichCandidate = async c => {
  let gov = null;
  try {
    const q = c.siret || c.siren || c.nom;
    const response = await this.helpers.httpRequest({
      method: 'GET', url: GOV,
      qs: { q, page: 1, per_page: 5 },
      json: true, timeout: 10000
    });
    gov = chooseCompany(response.results || [], c.nom, c.siret);
  } catch (e) { return null; }
  if (!gov) return null;
  const siege = gov.siege || {};
  const siret = cleanNum(c.siret || siege.siret || gov.siret);
  const siren = cleanNum(gov.siren || c.siren || siret.slice(0, 9));
  if (!/^\d{14}$/.test(siret) || !/^\d{9}$/.test(siren) || known.has(siren)) return null;
  const naf = gov.activite_principale_naf25 || gov.activite_principale || gov.code_naf || null;
  const nafLabel = gov.libelle_activite_principale || gov.activite_principale_libelle || gov.libelle_naf || null;
  const secteur = [naf, nafLabel].filter(Boolean).join(' — ') || null;
  const effectif = effectifBucket(gov.tranche_effectif_salarie || gov.effectif_salarie || gov.tranche_effectif);
  const managers = arr(gov.dirigeants);
  const manager = managers.find(x => x && (x.nom || x.prenoms || x.denomination));
  const dirigeant = manager ? ([manager.prenoms, manager.nom].filter(Boolean).join(' ').trim() || manager.denomination || null) : null;
  let dep = c.departement || String(siege.code_postal || gov.code_postal || '').slice(0, 2) || null;
  if (dep === '20') dep = String(siege.code_commune || '').startsWith('2A') ? '2A' : '2B';
  if (dep && /^\d$/.test(dep)) dep = '0' + dep;
  const companyName = gov.nom_complet || gov.nom_raison_sociale || gov.denomination || c.nom;
  let activity = c.domaine_activite || nafLabel || secteur;
  const webHits = await searchResults(companyName + ' ' + (dep || '') + ' site officiel contact');
  const businessHit = webHits.find(x => !/pappers|societe\.com|annuaire-entreprises\.data\.gouv\.fr/i.test(x.host)) || null;
  let website = null, sourceUrl = c.source_url || (businessHit && businessHit.url) || null;
  let email = null, emailType = null, pageOk = false;
  const pageHit = businessHit || (sourceUrl ? {url: sourceUrl, host: new URL(sourceUrl).hostname} : null);
  if (pageHit) {
    if (businessHit && !/pagesjaunes|annuaire|marches-publics|achatpublic|aws-achat|klekoon|e-marchespublics/i.test(businessHit.host)) website = new URL(businessHit.url).origin;
    const firstPage = await getPage(website || pageHit.url);
    pageOk = firstPage.length > 0;
    email = extractEmail(firstPage);
    if (!email) {
      const paths = ['/contact', '/nous-contacter', '/mentions-legales'];
      for (const path of paths) {
        const base = website || (pageHit.url ? new URL(pageHit.url).origin : null);
        if (!base) continue;
        const html = await getPage(base + path);
        email = extractEmail(html);
        if (email) { pageOk = pageOk || html.length > 0; break; }
      }
    }
    if (!email && website && pageOk) {
      const host = new URL(website).hostname.replace(/^www\./, '');
      const personParts = String(dirigeant || '').toLocaleLowerCase('fr').normalize('NFD').replace(/[\u0300-\u036f]/g, '').split(/[^a-z0-9]+/).filter(Boolean);
      const guesses = ['contact@' + host, 'info@' + host];
      if (personParts.length >= 2) guesses.push(personParts[0] + '.' + personParts[personParts.length - 1] + '@' + host);
      email = guesses.find(x => emailRe.test(x)) || null;
      if (email) emailType = 'deduit';
    } else if (email) emailType = 'publie';
  }
  if (!email && businessHit && businessHit.snippet) {
    email = extractEmail(businessHit.snippet);
    if (email) emailType = 'publie';
  }
  if (!email || !emailRe.test(email) || !activity || !effectif || !dep || !siret || !siren || !secteur || !dirigeant) return null;
  const lead = {
    siret, siren, nom: String(companyName).slice(0, 300), departement: dep,
    secteur: String(secteur).slice(0, 300), domaine_activite: String(activity).slice(0, 500),
    effectif_tranche: effectif, dirigeant: String(dirigeant).slice(0, 200),
    email: email.toLowerCase(), email_type: emailType || 'publie',
    email_statut: emailType === 'deduit' ? 'format_domaine_verifies_a_confirmer' : 'publie',
    email_valide: emailType !== 'deduit',
    site_web: website, source_type: c.source_type || (businessHit ? 'recherche_web' : 'annuaire'),
    source_url: sourceUrl || (businessHit && businessHit.url) || null,
    source_marche: c.source_marche || null, date_attribution: c.date_attribution || null,
    montant_marche: c.montant_marche || null, statut: 'à contacter',
    trouve_le: new Date().toISOString()
  };
  if (!lead.source_url) return null;
  known.add(siren);
  return { lead, rank: rankSize(effectif) };
};
const foundSmall = [], foundLarge = [];
