      response = await this.helpers.httpRequest({
        method: 'GET', url: BOAMP,
        qs: {
          where: fallbackFilter ? 'nature!="APPEL_OFFRE"' : 'nature="ATTRIBUTION"',
          order_by: 'dateparution desc', limit: 100, offset
        },
        json: true, timeout: 30000
      });
