    const results = response.results || [];
    if (!results.length && !fallbackFilter) { fallbackFilter = true; offset = 0; continue; }
    totalAvis = response.total_count || totalAvis;
    avisLus += results.length;
    for (const r of results) {
      await addCandidate(candidatesFromNotice(r));
      if (alreadyEnough()) break;
    }
    if (alreadyEnough() || results.length < 100 || (totalAvis && offset + results.length >= totalAvis)) break;
    offset += results.length;
  }
} catch (e) { error = 'BOAMP : ' + String(e.message || e).slice(0, 250); }
if (foundSmall.length < target) {
  const regions = [
